#define _GNU_SOURCE
#include "database.h"
#include <glib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <stdlib.h>
static sqlite3 *g_db;
sqlite3 *db_handle(void){return g_db;}
static void hash_password(const char *password,char *out,size_t cap){char *h=g_compute_checksum_for_string(G_CHECKSUM_SHA256,password,-1);snprintf(out,cap,"%s",h?h:"");g_free(h);}
static int exec_sql(const char *sql){char *err=NULL;int rc=sqlite3_exec(g_db,sql,NULL,NULL,&err);if(err)sqlite3_free(err);return rc==SQLITE_OK?0:-1;}
int db_open(const char *path){if(sqlite3_open(path,&g_db)!=SQLITE_OK)return -1;sqlite3_busy_timeout(g_db,5000);const char *schema=
"PRAGMA journal_mode=WAL;PRAGMA foreign_keys=ON;"
"CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,display_name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'STUDENT',created_at TEXT DEFAULT CURRENT_TIMESTAMP);"
"CREATE TABLE IF NOT EXISTS problems(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT NOT NULL,input_desc TEXT DEFAULT '',output_desc TEXT DEFAULT '',sample_in TEXT DEFAULT '',sample_out TEXT DEFAULT '',time_limit INTEGER DEFAULT 2,created_at TEXT DEFAULT CURRENT_TIMESTAMP);"
"CREATE TABLE IF NOT EXISTS test_cases(id INTEGER PRIMARY KEY AUTOINCREMENT,problem_id INTEGER NOT NULL REFERENCES problems(id) ON DELETE CASCADE,input TEXT NOT NULL,output TEXT NOT NULL);"
"CREATE TABLE IF NOT EXISTS submissions(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT NOT NULL,problem_id INTEGER NOT NULL,problem_title TEXT NOT NULL,status TEXT NOT NULL,score INTEGER NOT NULL,detail TEXT NOT NULL,submitted_at TEXT DEFAULT CURRENT_TIMESTAMP);"
"CREATE TABLE IF NOT EXISTS activity_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,message TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);";
if(exec_sql(schema)<0)return -1;
db_add_user("admin","admin123","Administrator","ADMIN");db_add_user("student","student123","Demo Student","STUDENT");
if(db_count("problems")==0){OJProblem p={0};p.id=1;strcpy(p.title,"Sum Two Numbers");strcpy(p.description,"Read two integers A and B and print their sum.");strcpy(p.input_desc,"Two integers A and B separated by whitespace.");strcpy(p.output_desc,"Print A + B.");strcpy(p.sample_in,"3 5");strcpy(p.sample_out,"8");p.time_limit=2;db_add_problem(&p);db_add_test(1,"1 2\n","3\n");db_add_test(1,"3 5\n","8\n");db_add_test(1,"-4 9\n","5\n");
memset(&p,0,sizeof p);p.id=2;strcpy(p.title,"Find Maximum");strcpy(p.description,"Read three integers and print the largest value.");strcpy(p.input_desc,"Three integers a, b and c.");strcpy(p.output_desc,"Print the maximum value.");strcpy(p.sample_in,"4 9 2");strcpy(p.sample_out,"9");p.time_limit=2;db_add_problem(&p);db_add_test(2,"4 9 2\n","9\n");db_add_test(2,"-1 -5 -3\n","-1\n");db_add_test(2,"7 7 2\n","7\n");
memset(&p,0,sizeof p);p.id=3;strcpy(p.title,"Even or Odd");strcpy(p.description,"Read an integer N. Print EVEN if it is even, otherwise print ODD.");strcpy(p.input_desc,"One integer N.");strcpy(p.output_desc,"Print EVEN or ODD.");strcpy(p.sample_in,"7");strcpy(p.sample_out,"ODD");p.time_limit=2;db_add_problem(&p);db_add_test(3,"7\n","ODD\n");db_add_test(3,"8\n","EVEN\n");db_add_test(3,"0\n","EVEN\n");}
return 0;}
void db_close(void){if(g_db){sqlite3_close(g_db);g_db=NULL;}}
int db_auth(const char *u,const char *pw,char *role,size_t cap){sqlite3_stmt*s;char h[80];hash_password(pw,h,sizeof h);if(sqlite3_prepare_v2(g_db,"SELECT role FROM users WHERE username=? AND password_hash=?",-1,&s,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,u,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,h,-1,SQLITE_TRANSIENT);int ok=sqlite3_step(s)==SQLITE_ROW;if(ok)snprintf(role,cap,"%s",sqlite3_column_text(s,0));sqlite3_finalize(s);return ok;}
int db_add_user(const char*u,const char*pw,const char*n,const char*r){sqlite3_stmt*s;char h[80];hash_password(pw,h,sizeof h);if(sqlite3_prepare_v2(g_db,"INSERT OR IGNORE INTO users(username,password_hash,display_name,role) VALUES(?,?,?,?)",-1,&s,NULL)!=SQLITE_OK)return -1;sqlite3_bind_text(s,1,u,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,h,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,n,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,r,-1,SQLITE_TRANSIENT);int rc=sqlite3_step(s)==SQLITE_DONE?sqlite3_changes(g_db): -1;sqlite3_finalize(s);return rc;}
#define COLTXT(s,i,dst) snprintf((dst),sizeof(dst),"%s",sqlite3_column_text((s),(i))?(const char*)sqlite3_column_text((s),(i)):"")
int db_list_problems(OJProblem*a,int cap){sqlite3_stmt*s;int n=0;if(sqlite3_prepare_v2(g_db,"SELECT id,title,description,input_desc,output_desc,sample_in,sample_out,time_limit FROM problems ORDER BY id",-1,&s,NULL)!=SQLITE_OK)return -1;while(n<cap&&sqlite3_step(s)==SQLITE_ROW){OJProblem*p=&a[n++];p->id=sqlite3_column_int(s,0);COLTXT(s,1,p->title);COLTXT(s,2,p->description);COLTXT(s,3,p->input_desc);COLTXT(s,4,p->output_desc);COLTXT(s,5,p->sample_in);COLTXT(s,6,p->sample_out);p->time_limit=sqlite3_column_int(s,7);}sqlite3_finalize(s);return n;}
int db_get_problem(int id,OJProblem*p){sqlite3_stmt*s;if(sqlite3_prepare_v2(g_db,"SELECT id,title,description,input_desc,output_desc,sample_in,sample_out,time_limit FROM problems WHERE id=?",-1,&s,NULL)!=SQLITE_OK)return -1;sqlite3_bind_int(s,1,id);int ok=sqlite3_step(s)==SQLITE_ROW;if(ok){p->id=sqlite3_column_int(s,0);COLTXT(s,1,p->title);COLTXT(s,2,p->description);COLTXT(s,3,p->input_desc);COLTXT(s,4,p->output_desc);COLTXT(s,5,p->sample_in);COLTXT(s,6,p->sample_out);p->time_limit=sqlite3_column_int(s,7);}sqlite3_finalize(s);return ok;}
int db_add_problem(const OJProblem*p){sqlite3_stmt*s;const char*q="INSERT INTO problems(title,description,input_desc,output_desc,sample_in,sample_out,time_limit) VALUES(?,?,?,?,?,?,?)";if(sqlite3_prepare_v2(g_db,q,-1,&s,NULL)!=SQLITE_OK)return -1;sqlite3_bind_text(s,1,p->title,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,p->description,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,p->input_desc,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,p->output_desc,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,5,p->sample_in,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,6,p->sample_out,-1,SQLITE_TRANSIENT);sqlite3_bind_int(s,7,p->time_limit?p->time_limit:2);int rc=sqlite3_step(s)==SQLITE_DONE?sqlite3_last_insert_rowid(g_db):-1;sqlite3_finalize(s);return (int)rc;}
int db_update_problem(const OJProblem*p){sqlite3_stmt*s;const char*q="UPDATE problems SET title=?,description=?,input_desc=?,output_desc=?,sample_in=?,sample_out=?,time_limit=? WHERE id=?";if(sqlite3_prepare_v2(g_db,q,-1,&s,NULL)!=SQLITE_OK)return -1;sqlite3_bind_text(s,1,p->title,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,p->description,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,p->input_desc,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,p->output_desc,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,5,p->sample_in,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,6,p->sample_out,-1,SQLITE_TRANSIENT);sqlite3_bind_int(s,7,p->time_limit);sqlite3_bind_int(s,8,p->id);int rc=sqlite3_step(s)==SQLITE_DONE?sqlite3_changes(g_db):-1;sqlite3_finalize(s);return rc;}
int db_delete_problem(int id){sqlite3_stmt*s;if(sqlite3_prepare_v2(g_db,"DELETE FROM problems WHERE id=?",-1,&s,NULL)!=SQLITE_OK)return -1;sqlite3_bind_int(s,1,id);int rc=sqlite3_step(s)==SQLITE_DONE?sqlite3_changes(g_db):-1;sqlite3_finalize(s);return rc;}
int db_list_tests(int id,OJTest*a,int cap){sqlite3_stmt*s;int n=0;if(sqlite3_prepare_v2(g_db,"SELECT id,problem_id,input,output FROM test_cases WHERE problem_id=? ORDER BY id",-1,&s,NULL)!=SQLITE_OK)return -1;sqlite3_bind_int(s,1,id);while(n<cap&&sqlite3_step(s)==SQLITE_ROW){OJTest*t=&a[n++];t->id=sqlite3_column_int(s,0);t->problem_id=sqlite3_column_int(s,1);COLTXT(s,2,t->input);COLTXT(s,3,t->output);}sqlite3_finalize(s);return n;}
int db_get_test(int id,OJTest*t){sqlite3_stmt*s;const char*q="SELECT id,problem_id,input,output FROM test_cases WHERE id=?";if(sqlite3_prepare_v2(g_db,q,-1,&s,NULL)!=SQLITE_OK)return 0;sqlite3_bind_int(s,1,id);int ok=sqlite3_step(s)==SQLITE_ROW;if(ok){t->id=sqlite3_column_int(s,0);t->problem_id=sqlite3_column_int(s,1);COLTXT(s,2,t->input);COLTXT(s,3,t->output);}sqlite3_finalize(s);return ok;}
int db_add_test(int id,const char*in,const char*out){sqlite3_stmt*s;if(sqlite3_prepare_v2(g_db,"INSERT INTO test_cases(problem_id,input,output) VALUES(?,?,?)",-1,&s,NULL)!=SQLITE_OK)return -1;sqlite3_bind_int(s,1,id);sqlite3_bind_text(s,2,in,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,out,-1,SQLITE_TRANSIENT);int rc=sqlite3_step(s)==SQLITE_DONE?sqlite3_last_insert_rowid(g_db):-1;sqlite3_finalize(s);return (int)rc;}
int db_update_test(int id,const char*in,const char*out){sqlite3_stmt*s;if(sqlite3_prepare_v2(g_db,"UPDATE test_cases SET input=?,output=? WHERE id=?",-1,&s,NULL)!=SQLITE_OK)return -1;sqlite3_bind_text(s,1,in,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,out,-1,SQLITE_TRANSIENT);sqlite3_bind_int(s,3,id);int rc=sqlite3_step(s)==SQLITE_DONE?sqlite3_changes(g_db):-1;sqlite3_finalize(s);return rc;}
int db_delete_test(int id){sqlite3_stmt*s;if(sqlite3_prepare_v2(g_db,"DELETE FROM test_cases WHERE id=?",-1,&s,NULL)!=SQLITE_OK)return -1;sqlite3_bind_int(s,1,id);int rc=sqlite3_step(s)==SQLITE_DONE?sqlite3_changes(g_db):-1;sqlite3_finalize(s);return rc;}
int db_save_submission(const char*u,int pid,const char*status,int score,const char*detail){OJProblem p={0};db_get_problem(pid,&p);sqlite3_stmt*s;if(sqlite3_prepare_v2(g_db,"INSERT INTO submissions(username,problem_id,problem_title,status,score,detail) VALUES(?,?,?,?,?,?)",-1,&s,NULL)!=SQLITE_OK)return -1;sqlite3_bind_text(s,1,u,-1,SQLITE_TRANSIENT);sqlite3_bind_int(s,2,pid);sqlite3_bind_text(s,3,p.title,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,status,-1,SQLITE_TRANSIENT);sqlite3_bind_int(s,5,score);sqlite3_bind_text(s,6,detail,-1,SQLITE_TRANSIENT);int rc=sqlite3_step(s)==SQLITE_DONE?sqlite3_last_insert_rowid(g_db):-1;sqlite3_finalize(s);return (int)rc;}
int db_update_submission(int id,const char*status,int score,const char*detail){sqlite3_stmt*s;if(sqlite3_prepare_v2(g_db,"UPDATE submissions SET status=?,score=?,detail=? WHERE id=?",-1,&s,NULL)!=SQLITE_OK)return -1;sqlite3_bind_text(s,1,status,-1,SQLITE_TRANSIENT);sqlite3_bind_int(s,2,score);sqlite3_bind_text(s,3,detail,-1,SQLITE_TRANSIENT);sqlite3_bind_int(s,4,id);int rc=sqlite3_step(s)==SQLITE_DONE?sqlite3_changes(g_db):-1;sqlite3_finalize(s);return rc;}
static int list_sub(const char*sql,const char*u,OJSubmission*a,int cap){sqlite3_stmt*s;int n=0;if(sqlite3_prepare_v2(g_db,sql,-1,&s,NULL)!=SQLITE_OK)return -1;if(u)sqlite3_bind_text(s,1,u,-1,SQLITE_TRANSIENT);while(n<cap&&sqlite3_step(s)==SQLITE_ROW){OJSubmission*t=&a[n++];t->id=sqlite3_column_int(s,0);COLTXT(s,1,t->username);t->problem_id=sqlite3_column_int(s,2);COLTXT(s,3,t->problem_title);COLTXT(s,4,t->status);t->score=sqlite3_column_int(s,5);COLTXT(s,6,t->detail);COLTXT(s,7,t->submitted_at);}sqlite3_finalize(s);return n;}
int db_list_submissions(const char*u,OJSubmission*a,int cap){return list_sub("SELECT id,username,problem_id,problem_title,status,score,detail,submitted_at FROM submissions WHERE username=? ORDER BY id DESC",u,a,cap);}
int db_list_all_submissions(OJSubmission*a,int cap){return list_sub("SELECT id,username,problem_id,problem_title,status,score,detail,submitted_at FROM submissions ORDER BY id DESC",NULL,a,cap);}
int db_leaderboard(char*out,size_t cap){sqlite3_stmt*s;size_t off=0;if(sqlite3_prepare_v2(g_db,"SELECT username,MAX(score) best,COUNT(*) attempts FROM submissions GROUP BY username ORDER BY best DESC,attempts ASC",-1,&s,NULL)!=SQLITE_OK)return -1;while(sqlite3_step(s)==SQLITE_ROW){int n=snprintf(out+off,cap>off?cap-off:0,"%s | Best: %d/10 | Submissions: %d\n",sqlite3_column_text(s,0),sqlite3_column_int(s,1),sqlite3_column_int(s,2));if(n>0)off+=(size_t)n;if(off>=cap)break;}sqlite3_finalize(s);return (int)off;}
int db_count(const char*t){char q[128];snprintf(q,sizeof q,"SELECT COUNT(*) FROM %s",t);sqlite3_stmt*s;int n=0;if(sqlite3_prepare_v2(g_db,q,-1,&s,NULL)==SQLITE_OK&&sqlite3_step(s)==SQLITE_ROW)n=sqlite3_column_int(s,0);sqlite3_finalize(s);return n;}
int db_log(const char*m){sqlite3_stmt*s;if(sqlite3_prepare_v2(g_db,"INSERT INTO activity_logs(message) VALUES(?)",-1,&s,NULL)!=SQLITE_OK)return -1;sqlite3_bind_text(s,1,m,-1,SQLITE_TRANSIENT);int rc=sqlite3_step(s)==SQLITE_DONE?0:-1;sqlite3_finalize(s);return rc;}
int db_list_logs(char*out,size_t cap){sqlite3_stmt*s;size_t off=0;if(sqlite3_prepare_v2(g_db,"SELECT created_at,message FROM activity_logs ORDER BY id DESC LIMIT 200",-1,&s,NULL)!=SQLITE_OK)return -1;while(sqlite3_step(s)==SQLITE_ROW){int n=snprintf(out+off,cap>off?cap-off:0,"[%s] %s\n",sqlite3_column_text(s,0),sqlite3_column_text(s,1));if(n>0)off+=(size_t)n;if(off>=cap)break;}sqlite3_finalize(s);return (int)off;}
